DELETE FROM control_tests WHERE tenant_id='gvnx';
DELETE FROM process_controls WHERE tenant_id='gvnx';
SELECT 'total' as i, count(*) FROM process_controls WHERE tenant_id='gvnx' UNION ALL SELECT 'key', count(*) FROM process_controls WHERE tenant_id='gvnx' AND key_control=true UNION ALL SELECT 'preventive', count(*) FROM process_controls WHERE tenant_id='gvnx' AND control_type='PREVENTIVE' UNION ALL SELECT 'detective', count(*) FROM process_controls WHERE tenant_id='gvnx' AND control_type='DETECTIVE' ORDER BY i;